svg.aria-label:
\begin{aligned}
\dot V_{\rm true}(x)
&=\nabla V(x)^\top f(x)+\delta\nabla V(x)^\top Bx\\
&\le-c\|x\|^2+|\delta|\,\|\nabla V(x)\|\,\|B\|\,\|x\|\\
&\le-c_\delta\|x\|^2.
\end{aligned}

